<?php
namespace App\Modules\CashManagement\Application;
use App\Modules\CashManagement\Domain\Models\CashSession;use App\Modules\CashManagement\Domain\Models\CashTransfer;use App\Modules\Finance\Domain\Enums\FinancialDocumentStatus;use App\Modules\Finance\Domain\Enums\PaymentDirection;use App\Modules\Finance\Domain\Models\Payment;
class ExpectedCashSessionBalance {public function execute(CashSession $session):int{$incoming=(int)Payment::query()->where('financial_account_id',$session->financial_account_id)->where('status',FinancialDocumentStatus::Confirmed)->where('direction',PaymentDirection::Incoming)->whereBetween('paid_at',[$session->opened_at,$session->closed_at??now()])->sum('amount');$outgoing=(int)Payment::query()->where('financial_account_id',$session->financial_account_id)->where('status',FinancialDocumentStatus::Confirmed)->where('direction',PaymentDirection::Outgoing)->whereBetween('paid_at',[$session->opened_at,$session->closed_at??now()])->sum('amount');$transfersIn=(int)CashTransfer::query()->where('to_account_id',$session->financial_account_id)->where('status',FinancialDocumentStatus::Confirmed)->whereBetween('transferred_at',[$session->opened_at,$session->closed_at??now()])->sum('amount');$transfersOut=(int)CashTransfer::query()->where('from_account_id',$session->financial_account_id)->where('status',FinancialDocumentStatus::Confirmed)->whereBetween('transferred_at',[$session->opened_at,$session->closed_at??now()])->sum('amount');return $session->opening_amount+$incoming-$outgoing+$transfersIn-$transfersOut;}}
